import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Atajos (página de configuración)","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/hotkeys-page.md","filePath":"es-ES/user-guide/settings/hotkeys-page.md","lastUpdated":1785993908000}'),n={name:"es-ES/user-guide/settings/hotkeys-page.md"};function i(s,e,l,c,d,p){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="atajos-pagina-de-configuracion" tabindex="-1">Atajos (página de configuración) <a class="header-anchor" href="#atajos-pagina-de-configuracion" aria-label="Permalink to &quot;Atajos (página de configuración)&quot;">​</a></h1><p>Tres pestañas: <strong>Global</strong>, <strong>Acciones de plugins</strong> y <strong>Lista negra de procesos</strong>. Ver la página de <a href="./../hotkeys.html">Atajos de teclado</a> para saber qué hace realmente cada atajo — esta página documenta la propia interfaz de configuración.</p><h2 id="global" tabindex="-1">Global <a class="header-anchor" href="#global" aria-label="Permalink to &quot;Global&quot;">​</a></h2><p>Grupo <strong>Atajos globales</strong>:</p><ul><li><strong>Mostrar/Ocultar búsqueda rápida</strong> — control grabador; acepta un modificador suelto (modo de doble pulsación, <code>Ctrl</code> por defecto) o una combinación completa. Junto a él, <strong>Seguir respondiendo mientras una app a pantalla completa tiene el foco</strong> — casilla, desactivada por defecto — excluye este atajo (y Cambio rápido, y la activación de la búsqueda en línea) de la exención automática de pantalla completa descrita en <a href="#process-blacklist">Lista negra de procesos</a> más abajo.</li><li><strong>Cambio rápido</strong> — <code>Ctrl+G</code> por defecto.</li></ul><p>Grupo <strong>Teclas de función</strong>:</p><ul><li>Elemento siguiente (<code>Ctrl+N</code>), Elemento anterior (<code>Ctrl+P</code>), modificador de Saltar a resultado (<code>Ctrl</code> por defecto, emparejado con los dígitos 1–9), Abrir menú de acciones (<code>Ctrl+O</code>), Completar desde selección (<code>Ctrl+Tab</code>), QuickLook (<code>Alt+P</code>), Historial de palabras clave anterior/siguiente (<code>Alt+Arriba</code> / <code>Alt+Abajo</code>), Eliminar entrada del historial de palabras clave (<code>Ctrl+Supr</code>), Abrir ventana completa (<code>Ctrl+F</code> por defecto — abre la ventana completa directamente, trasladando la consulta actual; el mismo efecto que hacer clic izquierdo en el propio logotipo de la Ventana rápida y elegir Mostrar ventana principal, sin ese clic adicional).</li><li>Todo grabador de aquí acepta cualquier tecla o combinación que pulses — incluidas teclas como una <code>Tab</code> suelta — y ese atajo tiene prioridad sobre cualquier significado predeterminado fijo que esa tecla pudiera tener por otro lado.</li></ul><p>Grupo <strong>Navegación rápida</strong>:</p><ul><li><strong>Doble clic izquierdo en espacio vacío</strong> — casilla, activada por defecto.</li><li><strong>Clic central en espacio vacío</strong> — casilla, activada por defecto.</li></ul><h2 id="acciones-de-plugins" tabindex="-1">Acciones de plugins <a class="header-anchor" href="#acciones-de-plugins" aria-label="Permalink to &quot;Acciones de plugins&quot;">​</a></h2><p>Una entrada por cada acción que haya registrado un plugin (por ejemplo, copiar ruta, ejecutar como administrador), agrupadas por nombre de plugin, cada una con su propio grabador de atajo. Recurre al valor predeterminado sugerido por el propio plugin hasta que lo cambies.</p><h2 id="process-blacklist" tabindex="-1">Lista negra de procesos <a class="header-anchor" href="#process-blacklist" aria-label="Permalink to &quot;Lista negra de procesos {#process-blacklist}&quot;">​</a></h2><p>Añade nombres de ejecutables (por ejemplo, <code>juego.exe</code>) cuyo foco en primer plano deba suprimir por completo los atajos globales de Lertaro, la interceptación de pulsaciones de teclado y los disparadores de ratón de doble clic/clic central de navegación rápida. No distingue mayúsculas de minúsculas, el sufijo <code>.exe</code> es opcional. Admite el mismo patrón de añadir-uno / edición-masiva que las reglas de exclusión bajo <strong>Índice</strong>: un cuadro de texto de una sola entrada más <strong>Añadir proceso</strong>, una lista de entradas existentes, y un cuadro de texto masivo con <strong>Generar texto</strong> / <strong>Aplicar texto</strong>.</p><p>Esta es la solución para los conflictos de atajos con juegos a pantalla completa u otras aplicaciones que capturan la entrada de teclado en bruto — ver <a href="./../troubleshooting.html#el-atajo-global-no-responde">Solución de problemas</a>. Cualquier aplicación en primer plano que sea realmente de pantalla completa recibe automáticamente el mismo trato, sin necesidad de ninguna entrada aquí — a menos que <strong>Seguir respondiendo mientras una app a pantalla completa tiene el foco</strong> (en <strong>Global</strong>, junto a Mostrar/Ocultar búsqueda rápida) esté activado, lo cual excluye por completo de esa exención. En cualquier caso, un diálogo de archivos activo siempre está exento, así que la navegación rápida sigue funcionando ahí.</p>',14)])])}const m=a(n,[["render",i]]);export{g as __pageData,m as default};
